pub mod core;
pub mod models;
pub mod pipeline;

pub use core::{
    BoundingBox, DetectionResult, Device, ModelCache, OcrEngine, OcrError, OcrResult,
    RecognitionResult, TextDetector, TextRecognizer,
};
pub use models::{PaddleDetector, PaddleRecognizer};
pub use pipeline::TwoStagePipeline;

use crate::{models::backends::ort::OrtModel};

/// PaddleOCR v6 engine
pub type PaddleOcr<M> = TwoStagePipeline<PaddleDetector<M>, PaddleRecognizer<M>>;

// Injects autogenerated `CHARACTER_DICT`, `MODEL_NAME`, and `DETECTION_MODEL_BYTES` generated at build time.
include!(concat!(env!("OUT_DIR"), "/dictionary.rs"));

const DETECTION_MODEL_NAME: &str = "PP_OCRv6_tiny_det";
/// Embedded PaddlePaddle v6 ONNX model bytes for text detection.
pub static DETECTION_MODEL_BYTES: &[u8] =
    include_bytes!("../data/models/PP_OCRv6_tiny_det.onnx");

/// Instantiates the default bundled PaddleOCR pipeline on the requested hardware device.
///
/// Models and character dictionaries are loaded directly from embedded memory with zero disk access.
///
/// # Errors
///
/// Returns [`OcrError`] if model sessions cannot be initialized on the device.
pub fn default_engine(device: Device, max_batch_size: usize) -> Result<PaddleOcr<OrtModel>, OcrError> {
    let detection_model = OrtModel::new(device, DETECTION_MODEL_NAME, DETECTION_MODEL_BYTES)?;
    let detector = PaddleDetector::from_model(detection_model);
    let reconition_model = OrtModel::new(device, RECOGNITION_MODEL_NAME, RECOGNITION_MODEL_BYTES)?;
    let recognizer = PaddleRecognizer::from_model(reconition_model, max_batch_size);
    Ok(PaddleOcr::new(detector, recognizer))
}
